//! Version-pinned compact AD368 / compact+extended485F ASCII C_DD writers.
//! No Native codec/UI parity, optimistic state, mode/map or server ACK.
use anyhow::{ensure,Context,Result};
use super::{Runtime,SourceEpoch,java_room_settings as settings,source_send};
pub const EDIT_SHA:&str="A13ECBFE9DC9BFCBA1D32649C829FB960DA995591C59C8613BB403FA4D62C168";
pub const NATIVE_SHA:&str="7E09849B4F0D442E04457AEE7E6DBEEB3D106437D9689AE8060323CE36FCB59E";
pub const MAX_REQUESTS:usize=32;
pub const SETTINGS_485F_SHA:&str="485F599DA9BA1A13504CB48DDCA3D53C6CAD91D7BAFDF738D104E65A05E1DFD5";
pub const SETTINGS_485F_NETWORK_SHA:&str="8C1776AA503098E09B42EFE8CA45E07E651DD4570A07CB6A8994006421CCEF41";
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Producer {AD368,Settings485F}
impl Producer {pub fn sha256(self)->&'static str{match self{Self::AD368=>super::login_bootstrap::PRODUCER_SHA,Self::Settings485F=>SETTINGS_485F_SHA}}}
#[derive(Clone)]pub struct Adapter {producer:Producer}
impl Adapter {pub fn producer(&self)->Producer{self.producer}pub fn parse(raw:&[u8])->Result<Self>{ensure!(raw.len()<=1024,"edit writer adapter bound");let v:serde_json::Value=serde_json::from_slice(raw)?;ensure!(v["native_sha256"]==NATIVE_SHA,"pinned C_DD static boundary required");let producer=if v["kind"]=="modern_synthetic_AD368_compact_settings_request_v1"&&v["producer_sha256"]==super::login_bootstrap::PRODUCER_SHA&&v["edit_sha256"]==EDIT_SHA{Producer::AD368}else{ensure!(v["kind"]=="modern_synthetic_485F_settings_request_v1"&&v["producer_sha256"]==SETTINGS_485F_SHA&&v["network_sha256"]==SETTINGS_485F_NETWORK_SHA,"pinned485F extended settings writer required");Producer::Settings485F};Ok(Self{producer})}}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Inputs {pub name:Vec<u8>,pub attributes:u8,pub password:Vec<u8>,pub capacity:u16}
/// Finite, lossless ASCII candidate input policy, separate from Native raw
/// strings/unknown getters and the Java wider MS950 parser domain.
pub fn encode(input:&Inputs)->Result<Vec<u8>>{
 ensure!((1..=89).contains(&input.name.len())&&input.password.len()<=4,"compact ASCII name/password length");
 ensure!(input.name.iter().chain(&input.password).all(|b|(32..=126).contains(b)),"compact candidate requires ASCII without NUL/control");
 ensure!(input.attributes&!0x3c==0&&(input.attributes&4!=0)==!input.password.is_empty(),"compact attributes/password mismatch");ensure!((2..=100).contains(&input.capacity),"ordinary compact capacity2..100 required");
 let mut b=vec![221];b.extend(&input.name);b.push(0);b.push(input.attributes);b.extend(&input.password);b.push(0);b.extend(input.capacity.to_le_bytes());Ok(b)
}
#[cfg(test)]mod r524_tests {
 use super::*;
 fn inputs()->Inputs{Inputs{name:b"SetExtendedRoom".to_vec(),attributes:44,password:b"pw".to_vec(),capacity:4}}
 fn extension()->Extension{Extension{values:[2,1,7,9],selections:vec![3,6,8]}}
 fn record(serial:u64)->Request{let input=inputs();let tail=extension();let raw_body=encode_extended(&input,&tail).unwrap();Request{sequence:1,write_serial:serial,input,extension:Some(tail),producer:Producer::Settings485F,context:ContextKey{room_id:1,joined:settings::JoinedContext{ce_revision:1,source:b"SetNetMoon".to_vec(),source_revision:1,roster_revision:2,selected_slot:0,selected_alias:b"SetNetHost(SetNetMoon)".to_vec(),navigation_revision:3,channel:2}},phase:Phase::Queued,written_bytes:0,frame_bytes:raw_body.len()+2,raw_body,retirement:None}}
 #[test]fn explicit_485F_extended_domains_lengths_and_compact_tail_free(){let spec=serde_json::json!({"kind":"modern_synthetic_485F_settings_request_v1","producer_sha256":SETTINGS_485F_SHA,"network_sha256":SETTINGS_485F_NETWORK_SHA,"native_sha256":NATIVE_SHA});assert_eq!(Adapter::parse(&serde_json::to_vec(&spec).unwrap()).unwrap().producer(),Producer::Settings485F);for key in ["producer_sha256","network_sha256","native_sha256"]{let mut bad=spec.clone();bad[key]=serde_json::json!("unpinned");assert!(Adapter::parse(&serde_json::to_vec(&bad).unwrap()).is_err());}let old=serde_json::json!({"kind":"modern_synthetic_AD368_compact_settings_request_v1","producer_sha256":super::super::login_bootstrap::PRODUCER_SHA,"edit_sha256":EDIT_SHA,"native_sha256":NATIVE_SHA});assert_eq!(Adapter::parse(&serde_json::to_vec(&old).unwrap()).unwrap().producer(),Producer::AD368);let b=encode_extended(&inputs(),&extension()).unwrap();assert_eq!(b,b"\xddSetExtendedRoom\0\x2cpw\0\x04\0\x02\x01\x07\x09\x03\x03\x06\x08");assert_eq!(b.len(),31);assert_eq!(encode(&Inputs{name:b"SetCompactRoom".to_vec(),attributes:40,password:vec![],capacity:6}).unwrap(),b"\xddSetCompactRoom\0\x28\0\x06\0");for values in [[8,1,7,9],[2,3,7,9],[2,1,0,9],[2,1,128,9],[2,1,7,32],[0;4]]{assert!(encode_extended(&inputs(),&Extension{values,selections:vec![3]}).is_err());}for selections in [vec![1;9],vec![0],vec![3,0,8]]{assert!(encode_extended(&inputs(),&Extension{values:[2,1,7,9],selections}).is_err());}let min=Extension{values:[0;4],selections:vec![]};assert_eq!(encode_extended(&inputs(),&min).unwrap().len(),encode(&inputs()).unwrap().len()+5);let max=Inputs{name:vec![b'N';89],attributes:0x3c,password:b"1234".to_vec(),capacity:100};let tail=Extension{values:[7,2,127,31],selections:vec![255;8]};assert_eq!(encode_extended(&max,&tail).unwrap().len(),112);assert!(encode_extended(&Inputs{name:vec![b'N';90],..max},&tail).is_err());}
 #[test]fn extended_sender_partial_stale_foreign_failed_and_retired(){let seed=0x87546ca110203040u64;let mut sender=source_send::Sender::default();sender.seed_from_source(seed).unwrap();let ticket=sender.commit(sender.prepare_extended_ordinary_room_settings(&inputs(),&extension()).unwrap()).ticket;let raw=sender.view(&ticket).unwrap().bytes().unwrap().to_vec();assert_eq!(&raw[..2],&[33,0]);let key=seed.to_le_bytes();let mut previous=0;let decoded=raw[2..].iter().enumerate().map(|(i,b)|{let value=*b^key[i&7]^previous;previous=*b;value}).collect::<Vec<_>>();assert_eq!(decoded,encode_extended(&inputs(),&extension()).unwrap());let mut r=record(ticket.serial());for at in 0..33{let p=sender.report(&ticket,at,source_send::WriteOutcome::Written(1)).unwrap();r.report(ticket.serial(),&p,true);assert_eq!(r.written_bytes,at+1);assert_eq!(r.phase,if at==32{Phase::CompletedWrite}else{Phase::Queued});}assert!(sender.report(&ticket,33,source_send::WriteOutcome::Written(1)).is_err());for failure in [source_send::WriteOutcome::Failed,source_send::WriteOutcome::Written(0),source_send::WriteOutcome::WouldBlock]{let mut a=source_send::Sender::default();let mut b=source_send::Sender::default();a.seed_from_source(1).unwrap();b.seed_from_source(1).unwrap();let ta=a.commit(a.prepare_extended_ordinary_room_settings(&inputs(),&extension()).unwrap()).ticket;let tb=b.commit(b.prepare_extended_ordinary_room_settings(&inputs(),&extension()).unwrap()).ticket;assert_eq!(ta.serial(),tb.serial());let before=a.snapshot();assert!(a.report(&tb,0,source_send::WriteOutcome::Written(1)).is_err());assert_eq!(a.snapshot(),before);let mut r=record(ta.serial());let p=a.report(&ta,0,source_send::WriteOutcome::Written(1)).unwrap();r.report(ta.serial(),&p,true);let before=a.snapshot();assert!(a.report(&ta,0,source_send::WriteOutcome::Written(1)).is_err());assert_eq!(a.snapshot(),before);let p=a.report(&ta,1,failure).unwrap();r.report(ta.serial(),&p,true);assert_eq!((r.phase,r.written_bytes),(Phase::Retired,1));}let mut r=record(2);r.report(1,&source_send::Progress::Complete,true);assert_eq!(r.phase,Phase::Queued);r.report(2,&source_send::Progress::Complete,false);assert_eq!((r.phase,r.written_bytes),(Phase::Retired,0));}
}
/// Edit-tail values do not grant Create/Join/source/membership authority.
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Extension {pub values:[u8;4],pub selections:Vec<u8>}
pub fn encode_extended(input:&Inputs,tail:&Extension)->Result<Vec<u8>>{let mut b=encode(input)?;ensure!(tail.selections.len()<=8&&!tail.selections.contains(&0),"extended K0..8/nonzero selection bytes required");ensure!((tail.values==[0;4]&&tail.selections.is_empty())||(tail.values[0]<=7&&tail.values[1]<=2&&(1..=127).contains(&tail.values[2])&&tail.values[3]<=31),"extended options outside finite producer domain");b.extend(tail.values);b.push(tail.selections.len()as u8);b.extend(&tail.selections);Ok(b)}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct ContextKey {pub room_id:u32,pub joined:settings::JoinedContext}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Phase {Queued,CompletedWrite,Retired}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Request {pub sequence:u64,pub write_serial:u64,pub input:Inputs,pub extension:Option<Extension>,pub producer:Producer,pub context:ContextKey,pub phase:Phase,pub written_bytes:usize,pub raw_body:Vec<u8>,pub frame_bytes:usize,pub retirement:Option<&'static str>}
impl Request {fn report(&mut self,serial:u64,p:&source_send::Progress,current:bool){if serial!=self.write_serial||self.phase!=Phase::Queued{return;}if !current{self.phase=Phase::Retired;self.retirement=Some("settings context retired");return;}match p{source_send::Progress::Partial{offset,..}=>self.written_bytes=*offset,source_send::Progress::Complete=>{self.written_bytes=self.frame_bytes;self.phase=Phase::CompletedWrite;},source_send::Progress::Retired{..}=>{self.phase=Phase::Retired;self.retirement=Some("source write retired");}}}}
#[derive(Clone,Debug,Default,PartialEq,Eq)]pub struct Snapshot {pub revision:u64,pub requests:Vec<Request>}
#[derive(Clone)]pub struct Control {epoch:SourceEpoch,revision:u64,context:ContextKey,input:Inputs,extension:Option<Extension>,producer:Producer}
#[derive(Clone)]struct OwnedRequest {epoch:SourceEpoch,request:Request}
#[derive(Default)]pub(crate) struct State {pub(crate) adapter:Option<Adapter>,revision:u64,requests:Vec<OwnedRequest>}
impl State {
 fn snapshot(&self)->Snapshot{Snapshot{revision:self.revision,requests:self.requests.iter().map(|v|v.request.clone()).collect()}}
 fn invalidate(&mut self,reason:&'static str){for v in &mut self.requests{if v.request.phase==Phase::Queued{v.request.phase=Phase::Retired;v.request.retirement=Some(reason);}}}
 fn retire(&mut self){self.requests.clear();self.revision=0;}
}
impl Runtime {
 pub fn configure_java_room_settings_request_adapter(&mut self,a:Adapter)->Result<()>{ensure!(self.source_connection_epoch().is_none()&&self.java_room.key.phase==super::java_room_entry::Phase::Idle,"edit adapter must precede normal entry");self.java_settings_request.adapter=Some(a);Ok(())}
 pub fn java_room_settings_request_snapshot(&self)->Snapshot{self.java_settings_request.snapshot()}
 pub fn last_java_room_settings_request_checkpoint(&self)->Option<Snapshot>{self.last_settings_request_checkpoint.clone()}
 fn current_settings_request_context(&self)->Result<ContextKey>{ensure!(self.java_settings_request.adapter.as_ref().zip(self.java_settings.adapter.as_ref()).is_some_and(|(writer,receiver)|writer.producer.sha256()==receiver.producer_sha256())&&self.page==super::UiPage::Menu&&self.java_return.key.phase==super::java_return::Phase::Idle&&!self.entry_transfer.key.timer_active&&self.entry_navigation.queue.is_empty()&&self.java_room_self_snapshot().pending.is_none(),"compact settings request unavailable");let joined=self.admit_java_room_settings_context()?;let room_id=self.java_room.key.room.as_ref().context("edit joined room absent")?.id;Ok(ContextKey{room_id,joined})}
 pub fn java_room_settings_request_control(&self,input:Inputs)->Option<Control>{self.settings_request_control(input,None)}
 pub fn java_room_extended_settings_request_control(&self,input:Inputs,tail:Extension)->Option<Control>{self.settings_request_control(input,Some(tail))}
 fn settings_request_control(&self,input:Inputs,extension:Option<Extension>)->Option<Control>{let producer=self.java_settings_request.adapter.as_ref()?.producer;if extension.is_some()&&producer!=Producer::Settings485F{return None;}if self.source_send.snapshot().pending.is_some()||self.java_settings_request.requests.len()>=MAX_REQUESTS||(if let Some(t)=&extension{encode_extended(&input,t)}else{encode(&input)}).is_err(){return None;}Some(Control{epoch:self.source_scope.current_epoch().ok()?,revision:self.java_settings_request.revision,context:self.current_settings_request_context().ok()?,input,extension,producer})}
 pub fn handle_java_room_settings_request_control(&mut self,c:&Control)->Result<()>{
  self.source_scope.admit_epoch(&c.epoch)?;ensure!(self.java_settings_request.adapter.as_ref().is_some_and(|a|a.producer==c.producer)&&(c.extension.is_none()||c.producer==Producer::Settings485F)&&c.revision==self.java_settings_request.revision&&c.context==self.current_settings_request_context()?&&self.source_send.snapshot().pending.is_none()&&self.java_settings_request.requests.len()<MAX_REQUESTS,"retired, consumed or unavailable compact edit control");
  let revision=self.java_settings_request.revision.checked_add(1).context("edit intent revision exhausted")?;let(body,prepared)=if let Some(tail)=&c.extension{(encode_extended(&c.input,tail)?,self.source_send.prepare_extended_ordinary_room_settings(&c.input,tail)?)}else{(encode(&c.input)?,self.source_send.prepare_ordinary_room_settings(&c.input)?)};let frame_bytes=body.len()+2;ensure!(prepared.reservation.frame_bytes==frame_bytes,"compact frame mismatch");let serial=prepared.reservation.ticket.serial();
  self.source_send.commit(prepared);self.java_settings_request.revision=revision;self.java_settings_request.requests.push(OwnedRequest{epoch:c.epoch.clone(),request:Request{sequence:revision,write_serial:serial,input:c.input.clone(),extension:c.extension.clone(),producer:c.producer,context:c.context.clone(),phase:Phase::Queued,written_bytes:0,raw_body:body,frame_bytes,retirement:None}});self.status="正在送出房間設定要求；結果尚未確認".into();Ok(())
 }
 pub(crate) fn note_java_room_settings_write(&mut self,serial:u64,p:&source_send::Progress){let context=self.current_settings_request_context().ok();let current=self.java_settings_request.requests.iter().find(|v|v.request.write_serial==serial).is_some_and(|v|self.source_scope.admit_epoch(&v.epoch).is_ok()&&context.as_ref()==Some(&v.request.context));if let Some(v)=self.java_settings_request.requests.iter_mut().find(|v|v.request.write_serial==serial){v.request.report(serial,p,current);}}
 pub(crate) fn invalidate_java_room_settings_request(&mut self){self.java_settings_request.invalidate("joined room invalidated");}
 pub(crate) fn archive_retire_java_room_settings_request(&mut self){if !self.java_settings_request.requests.is_empty(){self.java_settings_request.invalidate("source context retired");self.last_settings_request_checkpoint=Some(self.java_settings_request.snapshot());}self.java_settings_request.retire();}
}
#[cfg(test)]mod tests {
 use super::*;
 fn input()->Inputs{Inputs{name:b"EditAfterRoom".to_vec(),attributes:40,password:vec![],capacity:4}}
 fn request(serial:u64)->Request{let i=input();let b=encode(&i).unwrap();Request{sequence:1,write_serial:serial,input:i,extension:None,producer:Producer::AD368,context:ContextKey{room_id:1,joined:settings::JoinedContext{ce_revision:1,source:b"EditMoon".to_vec(),source_revision:1,roster_revision:2,selected_slot:0,selected_alias:b"EditHost(EditMoon)".to_vec(),navigation_revision:3,channel:2}},phase:Phase::Queued,written_bytes:0,frame_bytes:b.len()+2,raw_body:b,retirement:None}}
 #[test]fn ascii_bounds_mask_password_and_compact_layout(){assert_eq!(encode(&input()).unwrap(),b"\xddEditAfterRoom\0\x28\0\x04\0");let max=Inputs{name:vec![b'N';89],attributes:0x3c,password:b"1234".to_vec(),capacity:100};let b=encode(&max).unwrap();assert_eq!(b.len(),99);assert_eq!(&b[97..],&[100,0]);for n in [0,90]{let mut i=input();i.name=vec![b'N';n];assert!(encode(&i).is_err());}for bytes in [vec![0],vec![31],vec![127],vec![128],vec![0x81,0x40]]{let mut i=input();i.name=bytes.clone();assert!(encode(&i).is_err());i=input();i.password=bytes;i.attributes|=4;assert!(encode(&i).is_err());}for cap in [0,1,101,200,65535]{let mut i=input();i.capacity=cap;assert!(encode(&i).is_err());}for attrs in [1,2,4,64,128,255]{let mut i=input();i.attributes=attrs;assert!(encode(&i).is_err());}let mut i=input();i.password=b"12345".to_vec();i.attributes|=4;assert!(encode(&i).is_err());i=input();i.password=b"X".to_vec();assert!(encode(&i).is_err());i.attributes|=4;encode(&i).unwrap();}
 #[test]fn real_sender_compact_partial_full_foreign_failure_retired(){let seed=0x87546ca110203040u64;let mut sender=source_send::Sender::default();sender.seed_from_source(seed).unwrap();let ticket=sender.commit(sender.prepare_ordinary_room_settings(&input()).unwrap()).ticket;let raw=sender.view(&ticket).unwrap().bytes().unwrap().to_vec();assert_eq!(&raw[..2],&[21,0]);let k=seed.to_le_bytes();let mut prev=0;let body=raw[2..].iter().enumerate().map(|(n,b)|{let out=*b^k[n&7]^prev;prev=*b;out}).collect::<Vec<_>>();assert_eq!(body,b"\xddEditAfterRoom\0\x28\0\x04\0");let mut record=request(ticket.serial());for at in 0..21{let p=sender.report(&ticket,at,source_send::WriteOutcome::Written(1)).unwrap();record.report(ticket.serial(),&p,true);if at<20{assert_eq!(record.phase,Phase::Queued);}else{assert_eq!(record.phase,Phase::CompletedWrite);}}assert!(sender.report(&ticket,21,source_send::WriteOutcome::Written(1)).is_err());for failure in [source_send::WriteOutcome::Failed,source_send::WriteOutcome::Written(0),source_send::WriteOutcome::WouldBlock]{let mut a=source_send::Sender::default();let mut b=source_send::Sender::default();a.seed_from_source(1).unwrap();b.seed_from_source(1).unwrap();let ta=a.commit(a.prepare_ordinary_room_settings(&input()).unwrap()).ticket;let tb=b.commit(b.prepare_ordinary_room_settings(&input()).unwrap()).ticket;assert_eq!(ta.serial(),tb.serial());let before=a.snapshot();assert!(a.report(&tb,0,source_send::WriteOutcome::Written(1)).is_err());assert_eq!(a.snapshot(),before);let mut r=request(ta.serial());let p=a.report(&ta,0,source_send::WriteOutcome::Written(1)).unwrap();r.report(ta.serial(),&p,true);let before=a.snapshot();assert!(a.report(&ta,0,source_send::WriteOutcome::Written(1)).is_err());assert_eq!(a.snapshot(),before);let p=a.report(&ta,1,failure).unwrap();r.report(ta.serial(),&p,true);assert_eq!(r.phase,Phase::Retired);assert_eq!(r.written_bytes,1);}let mut r=request(2);r.report(1,&source_send::Progress::Complete,true);assert_eq!(r.phase,Phase::Queued);r.report(2,&source_send::Progress::Complete,false);assert_eq!(r.phase,Phase::Retired);assert_eq!(r.written_bytes,0);}
}
